package com.hostelfind.controller;
import com.hostelfind.dto.ClaimRequest; import com.hostelfind.model.*; import com.hostelfind.service.ClaimService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/claims") @CrossOrigin(origins="*") public class ClaimController { private final ClaimService service; public ClaimController(ClaimService s){service=s;} @PostMapping public ResponseEntity<Claim> create(@Valid @RequestBody ClaimRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));}@GetMapping("/item/{itemId}") public List<Claim> itemClaims(@PathVariable Long itemId){return service.forItem(itemId);}@PutMapping("/{id}") public Claim update(@PathVariable Long id,@RequestParam ClaimStatus status){return service.update(id,status);} }
